C = {}

# ---------- female.tex ----------
C["f3207"] = r"""把激素周期与性欲对应起来看，多数女性的模式是：卵泡期雌激素回升，欲望与阴道反应渐强，至排卵期前后到达峰值；黄体期孕激素主导，欲望回落，经前常伴随烦躁与不适。但个体差异极大——有人在经期反而欲望上升，有人在黄体期依赖身体的贴近而非性交。实用的做法是记录 2--3 个月的周期（欲望、情绪、身体感受与月经日期对照），找到自己的"高欲望窗口"，与伴侣沟通后把重要的亲密安排放在那个时段，事半功倍。另需知道：激素类避孕药可能拉平这种周期波动，若服药后发现性欲明显下降，可与医生讨论更换方案，而不必默默忍耐。"""

C["f3404"] = r"""温柔而坚定的拒绝有一个可复用的三层结构：先肯定关系（"我喜欢和你亲近"），再清晰拒绝（"但今天不想做"），最后按真实意愿给替代方案（"我们可以抱一会儿/洗澡/看个电影"）。要点有三：拒绝时不用编造理由——"头疼""明天要早起"式的托词反而邀请对方"帮你解决"；语气与身体语言要一致，边躲边笑的"不要"会被读成调情；替代方案必须是你真想做的，否则就是新的勉强。反过来，说出"不"也是一项值得练习的能力：从小场景开始（不想被拥抱时直接说），习惯于"拒绝不会毁掉关系"这个事实——如果一段关系经不起一次拒绝，问题在关系，不在拒绝。"""

C["f3436"] = r"""氟班色林（Flibanserin，商品名 Addyi）于 2015 年获美国 FDA 批准，是首个针对绝经前女性 HSDD 的处方药。它与"蓝色小药丸"机制完全不同：不直接增强欲望，而是通过调节 5-羟色胺等神经递质平衡来改善"欲望与抑制"的天平。疗效必须如实告知：临床试验中，服药者每月"有满意性欲的性事件"平均比安慰剂多约 0.5--1 次，属于"有帮助但非神奇"；禁忌与注意事项不少——与酒精同服可致严重低血压与晕厥，故须每日睡前服用且严格禁酒，与某些抗真菌药、抗生素同用也被禁止。2019 年 FDA 又批准了鼻喷剂布美诺肽（bremelanotide），按需给药。两者目前均未在中国大陆上市，且都强调应在排除关系问题、抑郁、药物影响等可逆因素后，经医生评估使用。"""

C["f4865"] = r"""性生活后的护理以"适度"为关键词。最有价值的一步是排尿——女性尿道短，事后排尿能冲刷尿道口细菌，对预防性交后尿路感染有实际意义。清洗方面，温水清洁外阴即可，阴道内部有自净机制（乳酸杆菌维持酸性环境），反复冲洗反而破坏菌群、增加感染机会。观察两件事：分泌物的颜色气味与有无出血——短暂、量少的接触后出血（尤其初次或久未性生活）多无碍，但反复出现或伴疼痛、异味的出血与分泌物，都值得做一次妇科检查排查宫颈与阴道病变。最后别忘了安全网：避孕套滑脱或破裂时，72 小时内的紧急避孕药与 5 天内的紧急宫内节育器是有效的补救手段，越早越好。"""

C["f11725"] = r"""关于就医时机有一条清晰分界：35 岁以下规律性生活未避孕满一年未孕、或 35 岁以上满半年未孕，即可启动不孕评估——且建议夫妇同查，男性精液分析无创又便宜，理应先行。辅助生殖技术的梯队从简到繁：诱导排卵（针对排卵障碍）、宫腔内人工授精（IUI，处理轻度精液异常或宫颈因素）、体外受精（IVF，即"试管婴儿"）及其衍生技术单精子注射（ICSI，针对严重少弱精）。成功率与年龄强相关：35 岁以下单周期 IVF 活产率可达 40\% 上下，40 岁以后明显下降，因此评估时机的把握本身就是治疗的一部分。此外，助产路往往伴随经济与情绪的双重消耗，提前与伴侣商定预算上限与"走到哪一步为止"，是许多人回望时最庆幸做过的事。"""

C["f12341"] = r"""妊娠与分娩对女性身体是一次系统性重塑，性方面亦然。孕期：早孕反应期的欲望普遍回落，孕中期常是相对舒适的窗口，孕晚期以侧卧等轻柔方式为主，有流产早产史、前置胎盘等情况须遵医嘱。分娩方式对盆底的影响各有不同——顺产可能带来暂时性的松弛与伤口瘢痕敏感，剖宫产也有自己的恢复课题，两者最终差异常比想象中小。产后的性重启以 6 周复查为起点而非红线：盆底肌评估与凯格尔训练应纳入常规；更要知道的是，产后性欲低下非常普遍（激素、哺乳、睡眠剥夺、身体意象与"母亲角色"的心理转换都在起作用），它需要的是时间、分工调整与伴侣的理解，而不是"赶紧恢复"的压力。何时恢复、以何种方式恢复，主动权始终在女性自己手里。"""

